class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry."""
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = {}
        # List order: LRU at index 0, MRU at index -1
        self.order = []

    def get(self, key, default=None):
        if key not in self.cache:
            return default

        # Move key to the end (MRU)
        self.order.remove(key)
        self.order.append(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            # Update existing key
            self.cache[key] = value
            # Move to MRU
            self.order.remove(key)
            self.order.append(key)
            return None

        # New key
        if len(self.cache) >= self.capacity:
            # Evict LRU
            lru_key = self.order.pop(0)
            del self.cache[lru_key]
            return lru_key

        # Add new key
        self.cache[key] = value
        self.order.append(key)
        return None

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        # Check existence without changing usage order
        return key in self.cache

    def keys(self):
        # Return keys from LRU to MRU
        return list(self.order)

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        evicted_keys = []
        while len(self.cache) > capacity:
            # Evict LRU
            lru_key = self.order.pop(0)
            del self.cache[lru_key]
            evicted_keys.append(lru_key)

        # Update capacity attribute
        self.capacity = capacity
        return evicted_keys

