        self._key_order: Dict[str, List[str]] = {}

    def sections(self) -> List[str]:
        """Returns the section names in the order they appear."""
        return self._section_order

    def keys(self, section: str) -> List[str]:
        """Returns the keys of a section in the order they appear."""
        if section not in self._sections:
            raise KeyError(f"Section '{section}' not found.")
        return self._key_order.get(section, [])

    def get(self, section: str, key: str, default: Optional[str] = None) -> Optional[str]:
        """Returns the value as a string, or default if missing."""
        if section not in self._sections:
            return default
        return self._sections[section].get(key, default)

    def getint(self, section: str, key: str, default: Optional[int] = None) -> Optional[int]:
        """Returns the value as an int, raising ValueError on failure."""
        val_str = self.get(section, key)
        if val_str is None: 
            return default

        try:
            # Check if the string contains only digits, an optional leading sign (+ or -), and no decimal points or hex prefixes.
