import typing

def search_rotated(a: typing.List[int], x: int) -> int:
    """
    Searches for x in a rotated sorted array a (distinct values).
    Returns the index of x, or -1 if not found. O(log n).
    """
    if not a:
        return -1

    low = 0
    high = len(a) - 1

    while low <= high:
        mid = low + (high - low) // 2

        if a[mid] == x:
            return mid

        # Check if the left half is sorted
        if a[low] <= a[mid]:
            # Left half is sorted
            if a[low] <= x < a[mid]:
                # x is in the sorted left half
                high = mid - 1
            else:
                # x must be in the unsorted right half
                low = mid + 1

        # Otherwise, the right half must be sorted
        else:
            # Right half is sorted (a[mid] < a[high])
            if a[mid] < x <= a[high]:
                # x is in the sorted right half
                low = mid + 1
            else:
                # x must be in the unsorted left half
                high = mid - 1

    return -1

