import typing

# --- Functions for standard sorted arrays ---

def first_index(a: typing.List[int], x: int) -> int:
    """Returns the index of the first element equal to x, or -1 if there is none."""
    low, high = 0, len(a) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            result = mid
            high = mid - 1  # Try to find an even earlier occurrence
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

def last_index(a: typing.List[int], x: int) -> int:
    """Returns the index of the last element equal to x, or -1 if there is none."""
    low, high = 0, len(a) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            result = mid
            low = mid + 1  # Try to find a later occurrence
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

def insertion_point(a: typing.List[int], x: int) -> int:
    """Returns the smallest index i such that inserting x before a[i] keeps a sorted (x goes before any equal elements). Returns len(a) if x is greater than every element."""
    low, high = 0, len(a)
    while low < high:
        mid = (low + high) // 2
        if a[mid] < x:
            low = mid + 1
        else:
            high = mid
    return low

def count(a: typing.List[int], x: int) -> int:
    """Returns how many elements equal x."""
    first = first_index(a, x)
    if first == -1:
        return 0
    last = last_index(a, x)
    return last - first + 1

# --- Functions for rotated sorted arrays ---

def rotation_offset(a: typing.List[int]) -> int:
    """Finds the index of the smallest element (rotation offset) in O(log n) time. Raises ValueError if a is empty."""
    if not a:
        raise ValueError("List cannot be empty for rotation_offset.")

    n = len(a)
    # If the array is not rotated, the offset is 0
    if a[0] <= a[n - 1]:
        return 0

    low, high = 0, n - 1

    while low < high:
        mid = (low + high) // 2

        # If a[mid] > a[high], the pivot (smallest element) must be in the right half (mid+1 to high)
        if a[mid] > a[high]:
            low = mid + 1
        # If a[mid] <= a[high], the pivot is mid or in the left half (low to mid)
        else:
            high = mid

    return low

def search_rotated(a: typing.List[int], x: int) -> int:
    """Searches for x in a rotated sorted array of distinct values. Returns index or -1."""
    if not a: 
        return -1

    # Find the rotation offset first
    offset = rotation_offset(a)
    n = len(a)

    # Create a conceptually sorted array view by indexing modulo n
    # Standard binary search on the logically sorted sequence
    low, high = 0, n - 1

    while low <= high:
        mid = (low + high) // 2
        # Map logical index 'mid' back to physical index in 'a'
        physical_mid = (mid + offset) % n

        if a[physical_mid] == x:
            return physical_mid
        elif a[physical_mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return -1

# --- Integer Square Root ---

def isqrt(n: int) -> int:
    """Returns the largest integer r such that r * r <= n. Raises ValueError if n is negative; TypeError if n is not an integer."""
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input cannot be negative for integer square root.")
    if n == 0 or n == 1:
        return n

    # Binary search approach for integer square root
    low = 1
    # A safe upper bound is n itself, but for efficiency, n//2 + 1 is often sufficient for large n.
    # Since n is an arbitrary large integer, using n is safe if we don't want to rely on sqrt(n).
    high = n
    result = 1

    while low <= high:
        mid = (low + high) // 2
        mid_sq = mid * mid

        if mid_sq <= n:
            result = mid  # This is a potential answer, try for a larger one
            low = mid + 1
        else:
            high = mid - 1

    return result

