class EmitError(Exception):
    """Custom exception raised when an error occurs during event emission."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.errors = []

class Emitter:
    """A simple synchronous event emitter."""
    def __init__(self):
        # Structure: {event: [(is_once, listener), ...]}
        self._listeners = {}

    def on(self, event, listener):
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append((False, listener))
