class Machine:
    """A Finite State Machine implementation."""
    def __init__(self, states: Union[List[State], List[str]], transitions: List[Transition], initial: str, context: Optional[object] = None):
        if not states:
            raise ValueError("States list cannot be empty.")

        self.context = context
        self.history: List[Tuple[str, str, str]] = []
        self._state_map: Dict[str, State] = {}
        self._state_names: Set[str] = set()

        # Process states
        for state_def in states:
            if isinstance(state_def, State):
                s = state_def
            else:
                s = State(name=state_def)

            if s.name in self._state_names:
                raise ValueError(f"Duplicate state name found: {s.name}")

            self._state_map[s.name] = s
            self._state_names.add(s.name)

        # Check initial state validity
        if initial not in self._state_names:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        # Check transitions
        for t in transitions:
            source = t.source
            is_valid_source = False
            if source == '*':
                is_valid_source = True
            elif isinstance(source, str) and source in self._state_names:
                is_valid_source = True
            elif isinstance(source, (list, tuple)) and all(s in self._state_names for s in source):
                is_valid_source = True

            if not is_valid_source:
                 raise ValueError(f"Transition source '{t.source}' references undefined state(s).")

            if t.target is not None and t.target not in self._state_names:
                raise ValueError(f"Transition target '{t.target}' references undefined state.")

        self.initial_state = initial
        self.state = initial
        self.transitions = transitions

    def reset(self):
        """Resets the state to initial and clears history without running hooks."""
        self.state = self.initial_state
        self.history = []

    def fire(self, event: str, **data) -> str:
        """Executes one transition based on the event according to 7 steps."""
        # Rule 7: Check for re-entrant calls
        if getattr(self, '_running_fire_call', False):
            raise MachineError("Cannot call fire while another fire call is in progress.")

        self._running_fire_call = True
        original_state = self.state
        chosen_transition: Optional[Transition] = None

        # 1. Find candidates
        candidates: List[Transition] = []
        for t in self.transitions:
            if t.event != event: 
                continue

            source = t.source
            is_source_match = False
            if source == '*':
                is_source_match = True
            elif isinstance(source, str) and source == original_state:
                is_source_match = True
            elif isinstance(source, (list, tuple)) and original_state in source:
                is_source_match = True

            if is_source_match:
                candidates.append(t)

        if not candidates:
            self._running_fire_call = False
            raise InvalidTransition(original_state, event)

        # 3. Evaluate guards
        for t in candidates:
            if t.guard is None:
                chosen_transition = t
                break

            # Build Event for guard evaluation. Target is defined as the transition's target, or original state for internal transition.
            guard_target = t.target if t.target is not None else original_state
            event_for_guard = Event(event, original_state, guard_target, data)

            try:
                if t.guard(self, event_for_guard):
                    chosen_transition = t
                    break
                # Guard failed, continue to next candidate
            except Exception as e:
                # Rule 6: Exception in guard propagates unchanged.
                self._running_fire_call = False
                raise e

        if chosen_transition is None:
            self._running_fire_call = False
            raise GuardRejected(original_state, event)

        # Setup for execution
        transition = chosen_transition
        is_internal = transition.target is None
        new_state = transition.target if not is_internal else original_state

        # 4 & 5. Execute transition logic
        try:
            # Run on_exit (Rule 4: Current state's on_exit)
            if not is_internal and self._state_map[original_state].on_exit is not None:
                # Target state for event hook is always the intended destination state
                on_exit_event = Event(event, original_state, new_state, data)
                self._state_map[original_state].on_exit(self, on_exit_event)

            # Run transition action (Rule 4/5)
            if transition.action is not None:
                action_event = Event(event, original_state, new_state if not is_internal else original_state, data)
                transition.action(self, action_event)

            if not is_internal:
                # Rule 4: Update state and append to history
                self.state = new_state
                self.history.append((original_state, event, new_state))

                # Rule 4: Run target state's on_enter
                if self._state_map[new_state].on_enter is not None:
                    on_enter_event = Event(event, original_state, new_state, data)
                    self._state_map[new_state].on_enter(self, on_enter_event)

                # Rule 4: Run on_transition listeners (placeholder for now)
                # self._run_listeners(original_state, event, new_state)

            else:
                # Rule 5: Internal transition - state unchanged, history recorded
                self.history.append((original_state, event, original_state))

        # Rule 6 Handling
        except MachineError as e:
            # Exception from guard, on_exit, or action: state/history unchanged
            # If the exception came from the guard, it was already caught and handled outside.
            # If it came from on_exit/action, we stop here.
            raise e
        except Exception as e:
            # Exception from on_enter or listener: state has already changed (if not internal)
            raise e

        finally:
            self._running_fire_call = False

        return self.state

    def can_fire(self, event: str, **data) -> bool:
        """Checks if a transition would be taken without side effects."""
        candidates: List[Transition] = []
        for t in self.transitions:
            if t.event != event:
                continue

            source = t.source
            is_source_match = False
            if source == '*':
                is_source_match = True
            elif isinstance(source, str) and source == self.state:
                is_source_match = True
            elif isinstance(source, (list, tuple)) and self.state in source:
                is_source_match = True

            if is_source_match:
                candidates.append(t)

        if not candidates:
            return False

        for t in candidates:
            if t.guard is None:
                return True

            # Check guard without side effects
            guard_target = t.target if t.target is not None else self.state
            event_for_guard = Event(event, self.state, guard_target, data)
            try:
                if t.guard(self, event_for_guard):
                    return True
            except Exception: 
                # If guard raises, it implies it might have side effects, but for can_fire, we treat failure as rejection.
                pass
        return False

    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated names of events that have at least one transition from the current state, ignoring guards."""
        available = set()
        for t in self.transitions:
            source = t.source
            is_source_match = False
            if source == '*':
                is_source_match = True
            elif isinstance(source, str) and source == self.state:
                is_source_match = True
            elif isinstance(source, (list, tuple)) and self.state in source:
                is_source_match = True

            if is_source_match:
                available.add(t.event)
        return sorted(list(available))

    def on_transition(self, listener: callable):
        """Adds a listener for state transitions. Implementation placeholder."""
        # In a full implementation, this would append the listener to a list.
        pass

    # Placeholder for listener execution, as per spec requirement in fire()
