        self.event = event

class GuardRejected(MachineError):
    """Raised by fire when every transition for the event from the current state was rejected by its guard."""
    def __init__(self, state, event):
        super().__init__(f"All transitions for event '{event}' from state '{state}' were rejected by their guards.")
        self.state = state
        self.event = event

class MachineError(Exception):
