    def can_fire(self, event: str, **data) -> bool:
        """Checks if the given event would cause a transition without side effects."""
        candidates = [t for t in self.transitions if t.event == event and self.state == t.source]
        if not candidates:
            return False

        for t in candidates:
            guard = t.guard
            if guard is None:
                return True
            try:
                # Guards must not have side effects
                if guard(self, Event(event, self.state, t.target, data)): 
                    return True
            except Exception:
                # If a guard raises, it's considered a failure for can_fire
                pass
        return False

    def available_events(self) -> list[str]:
        """Returns sorted, de-duplicated names of events available from the current state."""
        available = set()
        for t in self.transitions:
            if t.source == self.state and t.guard is None:
                available.add(t.event)
        return sorted(list(available))

    def on_transition(self, listener: callable): 
        """Adds a listener function to be called on every transition."""
        self.listeners.append(listener)

    def reset(self) -> None:
        """Resets the machine to its initial state and clears history."""
        self.state = self.initial
        self.history = []

    def _run_hook(self, hook_func: callable, machine_instance, event: Event, context_data: dict, is_guard_or_action: bool = False):
        """Helper to execute a hook and manage propagation/error handling."""
        try:
            result = hook_func(machine_instance, event)
            # Guards are expected to return truthy/falsy, actions/hooks return their value
            return result
        except Exception as e:
            # Propagate exception as required by step 6
            raise e

    def fire(self, event: str, **data) -> str:
        """Takes one transition based on the event and returns the new state name."""
        # Rule 7: Check for nested fire
        if hasattr(self, '_is_firing') and self._is_firing:
            raise MachineError("Cannot call fire while another fire is running.")

        self._is_firing = True
        try:
            # 1. Find candidates
            candidates = [t for t in self.transitions if t.event == event and t.source == self.state]
            if not candidates:
                raise InvalidTransition(state=self.state, event=event)

            # 2. Prepare data context
            event_data = data.copy()
            event = Event(event, self.state, None, event_data) # Target is placeholder for guards

            # 3. Evaluate guards
            chosen_transition = None
            for t in candidates:
                guard = t.guard
                if guard is None:
                    chosen_transition = t
                    break
                try:
                    # Evaluate guard
                    if guard(self, event):
                        chosen_transition = t
                        break
                except Exception:
                    # If guard fails, it's rejected, move to next candidate
                    pass

            if chosen_transition is None:
                raise GuardRejected(state=self.state, event=event)

            t = chosen_transition
            new_state = t.target if t.target is not None else self.state

            # 4. & 5. Run hooks and update state
            if t.target is not None:
                # Normal transition

                # 4a. Current state's on_exit
                if self.state.on_exit:
                    self._run_hook(self.state.on_exit, self, event, event_data, is_guard_or_action=True)

                # 4b. Transition's action
                if t.action:
                    self._run_hook(t.action, self, event, event_data, is_guard_or_action=True)

                # 4c. Set state and record history
                self.state = new_state
                history_entry = (self.state, event, new_state) if t.target is not None else (self.state, event, self.state)
                self.history.append(history_entry)

                # 4d. Target state's on_enter
                if self.state.on_enter:
                    self._run_hook(self.state.on_enter, self, event, event_data, is_guard_or_action=True)

                # 4e. Listeners
                for listener in self.listeners:
                    listener(self.state, event, new_state)

            else:
                # Internal transition (target=None)

                # 5a. Run action
                if t.action:
                    self._run_hook(t.action, self, event, event_data, is_guard_or_action=True)

                # 5b. Record history (target=source)
                history_entry = (self.state, event, self.state)
                self.history.append(history_entry)

                # 5c. Call listeners
                for listener in self.listeners:
                    listener(self.state, event, self.state)

            return self.state

        finally:
            self._is_firing = False

    # Initialization logic needs to be completed/assumed to be done in __init__ based on previous steps
    # Adding necessary setup for context/listeners to make the methods runnable/complete
    def __init__(self, states, transitions, initial: str, context=None):
        if not states:
            raise ValueError("States cannot be empty.")

        state_names = set()
        for item in states:
            if isinstance(item, str):
                state_names.add(item)
            elif hasattr(item, 'name'):
                state_names.add(item.name)

        if len(state_names) != len(states) and any(isinstance(s, str) for s in states):
            # Simple check for duplicate names if using strings
            pass # More complex checking might be needed if mixed types are allowed, but following spec.

        self.states_map = {s.name if hasattr(s, 'name') else s for s in states}
        for s in states:
            if isinstance(s, str) and s in state_names and state_names.count(s) > 1:
                 raise ValueError(f"State name '{s}' is duplicated.")

        if initial not in state_names:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        self.transitions = transitions
        self.initial = initial
        self.state = initial
        self.context = context
        self.history = []
        self.listeners = []
        self._is_firing = False

        # Final validation: check if transition sources/targets exist
        defined_states = {s.name if hasattr(s, 'name') else s for s in states}
        for t in transitions:
            # Check source
            source_valid = False
            if t.source == '*':
                source_valid = True
            elif isinstance(t.source, str) and t.source in defined_states:
                source_valid = True
            elif isinstance(t.source, (list, tuple)) and any(s in defined_states for s in t.source):
                source_valid = True

            if not source_valid:
                raise ValueError(f"Transition source '{t.source}' is not a valid state or '*'.")

            # Check target (if not None)
            if t.target is not None and t.target not in defined_states:
                 raise ValueError(f"Transition target '{t.target}' is not a valid state.")

