from fsm.machine import Machine, InvalidTransition, MachineError
from typing import Dict, Tuple, Any, List

class VendingError(Exception):
    """Base exception for vending machine errors."""
    pass

class SoldOut(VendingError):
    """Raised when a product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when the credit is less than the product price."""
    pass

class VendingMachine:
    """A vending machine built on the FSM library."""

    def __init__(self, products: Dict[str, Tuple[int, int]]):
        # products maps a product code to (price in cents, stock)
        self.products = products

        # --- FSM Setup ---
        # States: 'idle', 'credit', 'maintenance'
        self.states = ['idle', 'credit', 'maintenance']

        # Transition definitions (simplified for initial setup):
        self.transitions = [
            # Idle -> Credit (insert coin)
            Transition("insert", "idle", "credit"),
            # Idle -> Maintenance (service)
            Transition("service", "idle", "maintenance"),

            # Credit -> Idle (select item)
            Transition("select", "credit", "idle"),
            # Credit -> Idle (cancel)
            Transition("cancel", "credit", "idle"),

            # Maintenance -> Idle (resume)
            Transition("resume", "maintenance", "idle"),
            # Maintenance -> Maintenance (restock - self-loop for internal state change)
            Transition("restock", "maintenance", None),
        ]

        self.machine = Machine(self.states, self.transitions, initial="idle")

        # --- Vending Machine State ---
        self._credit: int = 0
        self._sales: Dict[str, int] = {}

        # Initial check: Machine state should match internal state
        assert self.machine.state == "idle"

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def _get_product_details(self, code: str) -> Tuple[int, int]:
        """Helper to safely retrieve product price and stock."""
        try:
            return self.products[code]
        except KeyError:
            raise KeyError(f"Unknown product code: {code}")

    def insert(self, coin: int) -> int:
        """Adds the coin to the credit, moves to 'credit' state, returns new credit."""
        if coin not in [5, 10, 25, 100]:
            raise ValueError("Invalid coin denomination. Accepted coins are 5, 10, 25, 100.")

        if self.state not in ['idle', 'credit']:
            raise InvalidTransition(self.machine.state, "insert")

        self._credit += coin

        # Transition: Insert coin -> Credit state
        try:
            self.machine.fire("insert", coin=coin)
        except MachineError as e:
            # Should not happen if state check is correct, but for robustness
            raise InvalidTransition(self.machine.state, "insert") from e

        return self._credit

    def select(self, code: str) -> List[int]:
        """Sells one unit, returns change, moves to 'idle' state."""
        if self.state != 'credit':
            raise InvalidTransition(self.machine.state, "select")

        try:
            price, stock = self._get_product_details(code)
        except KeyError as e:
            raise e # Re-raise unknown code

        if stock <= 0:
            raise SoldOut()

        if self._credit < price:
            raise InsufficientCredit()

        # --- Successful Transaction ---

        # 1. Update internal state (stock and sales)
        self.products[code] = (price, stock - 1)
        self._sales[code] = self._sales.get(code, 0) + 1

        # 2. Calculate change
        change_due = self._credit - price
        change_coins = self._calculate_change(change_due)

        # 3. Reset machine and credit
        self._credit = 0
        try:
            self.machine.fire("select", code=code, price=price)
        except MachineError as e:
             # Should not happen
             raise InvalidTransition(self.machine.state, "select") from e

        # The state transition handles moving to 'idle' after selection
        return change_coins

    def cancel(self) -> List[int]:
        """Refunds the whole credit, moves to 'idle' state."""
        if self.state != 'credit':
            raise InvalidTransition(self.machine.state, "cancel")

        refund_coins = self._calculate_change(self._credit)

        # Reset machine and credit
        self._credit = 0
        try:
            self.machine.fire("cancel", refund=refund_coins)
        except MachineError as e:
             # Should not happen
             raise InvalidTransition(self.machine.state, "cancel") from e

        return refund_coins

    def service(self) -> None:
        """Enters maintenance state from 'idle'."""
        if self.state != 'idle':
            raise InvalidTransition(self.machine.state, "service")

        # Transition: Idle -> Maintenance
        try:
            self.machine.fire("service",)
        except MachineError as e:
            raise InvalidTransition(self.machine.state, "service") from e

    def restock(self, code: str, qty: int, price: int = None) -> None:
        """Adds stock or updates price in maintenance state."""
        if self.state != 'maintenance':
            raise InvalidTransition(self.machine.state, "restock")
        if qty < 1:
            raise ValueError("Quantity must be 1 or more for restocking.")

        # Internal transition: Maintenance -> Maintenance (handled via Transition("restock", "maintenance", None))
        try:
            self.machine.fire("restock", code=code, qty=qty, price=price)
        except MachineError as e:
            raise InvalidTransition(self.machine.state, "restock") from e

        # Apply changes based on parameters
        if code not in self.products:
            if price is None:
                raise KeyError(f"Cannot restock new code '{code}' without specifying a price.")
            # New code
            self.products[code] = (price, qty)
        else:
            price_old, stock_old = self.products[code]
            if price is not None and price != price_old:
                # Update price
                self.products[code] = (price, stock_old)
            # Update stock (always happens)
            self.products[code] = (self.products[code][0], stock_old + qty)

    def resume(self) -> None:
        """Resumes normal operation from maintenance state."""
        if self.state != 'maintenance':
            raise InvalidTransition(self.machine.state, "resume")

        # Transition: Maintenance -> Idle
        try:
            self.machine.fire("resume",)
        except MachineError as e:
            raise InvalidTransition(self.machine.state, "resume") from e

    # --- Utility Methods ---

    def _calculate_change(self, amount: int) -> List[int]:
        """Calculates change using greedy algorithm (100, 25, 10, 5)."""
        coins = [100, 25, 10, 5]
        change_list = []
        remaining = amount
        for coin in coins:
            count = remaining // coin
            if count > 0:
                change_list.extend([coin] * count)
                remaining -= count * coin
        return change_list

    def stock(self, code: str) -> int:
        """Returns the current stock level for a product."""
        try:
            return self.products[code][1]
        except KeyError:
            raise KeyError(f"Unknown product code: {code}")

    def price(self, code: str) -> int:
        """Returns the price of a product in cents."""
        try:
            return self.products[code][0]
        except KeyError:
            raise KeyError(f"Unknown product code: {code}")

    @property
    def sales(self) -> Dict[str, int]:
        return self._sales

    @property
    def revenue(self) -> int:
        total_revenue = 0
        for code, count in self._sales.items():
            total_revenue += self.products[code][0] * count
        return total_revenue


    def _give_change(self, change_cents: int) -> List[int]:
        """Calculates the change using a greedy algorithm."""
        change_coins = []
        remaining = change_cents
        # Greedy order: 100, 25, 10, 5
        for coin in [100, 25, 10, 5]:
            while remaining >= coin:
                change_coins.append(coin)
                remaining -= coin
        return change_coins

    def select(self, code: str) -> List[int]:
        """Sells one unit of the specified product and returns change."""
        if self.state != 'credit':
            # This case should technically be caught by the FSM transition table,
            # but as a safeguard:
            raise InvalidTransition(self.state, 'select')

        if code not in self.products:
            raise KeyError(f"Product code '{code}' not found.")

        price, stock = self.products[code]

        if stock <= 0:
            raise SoldOut(f"Product '{code}' is sold out.")

        if self.credit < price:
            raise InsufficientCredit(f"Insufficient credit to purchase '{code}'. Need {price}, have {self.credit}.")

        # Successful transaction
        self.products[code] = (price, stock - 1)

        change_cents = self.credit - price
        self._give_change(change_cents)

        # Update state and credit
        self.credit = 0
        self.machine.fire('select', change=change_cents)

        # Update sales records
        self._sales[code] = self._sales.get(code, 0) + 1

        return self._give_change(change_cents)

    def cancel(self) -> List[int]:
        """Refunds the entire current credit."""
        if self.state != 'credit':
            raise InvalidTransition(self.state, 'cancel')

        # Refund the whole credit
        refund_coins = self._give_change(self.credit)
        self.credit = 0

        # Transition back to idle
        self.machine.fire('cancel')

        return refund_coins

    def service(self) -> None:
        """Initiates maintenance mode."""
        if self.state != 'idle':
            raise InvalidTransition(self.state, 'service')
        self.machine.fire('service')

    def restock(self, code: str, qty: int, price: int | None = None) -> None:
        """Adds stock or sets a new price while in maintenance."""
        if self.state != 'maintenance':
            raise InvalidTransition(self.state, 'restock')

        if qty < 1:
            raise ValueError("Restock quantity must be at least 1.")

        if code not in self.products and price is None:
            raise KeyError(f"Cannot add new product '{code}' without a price.")

        if code not in self.products and price is not None:
            # New product
            self.products[code] = (price, qty)
        else:
            # Existing product
            current_price, current_stock = self.products[code]
            self.products[code] = (price if price is not None else current_price, current_stock + qty)

    def resume(self) -> None:
        """Exits maintenance mode."""
        if self.state != 'maintenance':
            raise InvalidTransition(self.state, 'resume')
        self.machine.fire('resume')

    # --- Read-Only Views ---

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self.credit

    def stock(self, code: str) -> int:
        """Returns the current stock level for a product code."""
        return self.products[code][1]

    def price(self, code: str) -> int:
        """Returns the price in cents for a product code."""
        return self.products[code][0]

    @property
    def sales(self) -> Dict[str, int]:
        return self._sales

    @property
    def revenue(self) -> int:
        total_revenue = 0
        for code, count in self._sales.items():
            total_revenue += self.products[code][0] * count
        return total_revenue

