from typing import Optional, List, Union, Any, Dict, Tuple

# --- Exceptions ---

class MachineError(Exception):
    """Base class for FSM errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the current state and event."""
    def __init__(self, state: str, event: str):
        super().__init__(f"No transition found for event '{event}' leaving state '{state}'.")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    """Raised when all transitions for an event from a state are rejected by guards."""
    def __init__(self, state: str, event: str):
        super().__init__(f"All transitions for event '{event}' from state '{state}' were rejected by their guards.")
        self.state = state
        self.event = event

# --- Data Classes ---

