    source: str
    target: str
    data: dict

# --- Machine Class ---

class Machine:
    def __init__(self, states: Union[List[State], List[str]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        if not states:
            raise ValueError("States list cannot be empty.")

        state_names = set()
        state_map = {}

        # Process states to ensure unique names and map names to State objects if necessary
        processed_states = []
        for s in states:
            if isinstance(s, str):
                s_obj = State(name=s)
            elif isinstance(s, State):
                s_obj = s
            else:
                raise TypeError("State element must be a str or State object.")

            if s_obj.name in state_names:
                raise ValueError(f"Duplicate state name found: {s_obj.name}")
            state_names.add(s_obj.name)
            state_map[s_obj.name] = s_obj
            processed_states.append(s_obj)

        # Store initial state name for reset() functionality
        self.initial_state_name = initial

        # Validate initial state
        if initial not in state_names:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        self.state = initial
        self.context = context
        self.history: List[tuple[str, str, str]] = []
        self.state_map = state_map
        self.transitions = transitions
        self._listeners: List[Any] = []
        self._firing = False

        # Validate transitions
        for t in transitions:
            source_names = []
            if isinstance(t.source, str): 
                source_names = [t.source]
            elif isinstance(t.source, (list, tuple)): 
                source_names = t.source

            for name in source_names:
                if name not in state_names:
                    raise ValueError(f"Transition references unknown source state: '{name}'.")

            if t.target is not None and t.target not in state_names:
                raise ValueError(f"Transition references unknown target state: '{t.target}'.")

    def _run_hook(self, hook_func: Any, event: Event, machine: 'Machine'):
        """Executes a hook, passing machine and event."""
        hook_func(machine, event)

    def fire(self, event_name: str, **data) -> str:
        if self._firing:
            raise MachineError("Cannot call fire while another fire is in progress.")

        self._firing = True
        try:
            # 2. Create event data structure
            # Target is placeholder here, it will be set when transition is found.
            event = Event(name=event_name, source=self.state, target='_internal_placeholder_', data=data)

            # 1. Find candidates
            candidates = []
            for t in self.transitions:
                if t.event == event_name:
                    source_matches = False
                    if isinstance(t.source, str): 
                        if t.source == self.state: source_matches = True
                    elif isinstance(t.source, (list, tuple)): 
                        if self.state in t.source: source_matches = True
                    elif t.source == '*':
                        source_matches = True

                    if source_matches:
                        candidates.append(t)

            if not candidates:
                raise InvalidTransition(self.state, event_name)

            # 3. Evaluate guards
            chosen_transition: Optional[Transition] = None
            for t in candidates:
                if t.guard is None:
                    chosen_transition = t
                    break
                try:
                    # Guards must not have side effects.
                    if t.guard(self, event): 
                        chosen_transition = t
                        break
                except MachineError: # Catching exceptions from guards as per rule 6
                    # If guard raises an exception, the transition is implicitly rejected
                    pass

            if chosen_transition is None:
                raise GuardRejected(self.state, event_name)

            t = chosen_transition
            target_state = t.target if t.target is not None else self.state
            new_state = target_state

            # 4. Normal transition execution order (State change occurs)
            if t.target is not None:
                # 4a. On exit of current state
                current_state_obj = self.state_map[self.state]
                if current_state_obj.on_exit is not None:
                    self._run_hook(current_state_obj.on_exit, event, self)

                # 4b. Transition action
                if t.action is not None:
                    self._run_hook(t.action, event, self)

                # State update and history logging
                self.state = new_state
                self.history.append((self.state, event_name, new_state))

                # 4c. On enter of target state
                target_state_obj = self.state_map[new_state]
                if target_state_obj.on_enter is not None:
                    self._run_hook(target_state_obj.on_enter, event, self)

                # 4d. Listeners
                for listener in self._listeners:
                    listener(self.state, event_name, new_state)

            # 5. Internal transition (State remains the same)
            else: # target is None
                # 5a. Action only
                if t.action is not None:
                    self._run_hook(t.action, event, self)

                # History and listeners
                self.history.append((self.state, event_name, self.state))
                for listener in self._listeners:
                    listener(self.state, event_name, self.state)

            return self.state

        except MachineError as e:
            # Rule 6: Exception propagation
            raise e
        except Exception as e:
            # Catching other exceptions from hooks/guards to propagate them unchanged (Rule 6)
            raise e
        finally:
            self._firing = False

    def can_fire(self, event_name: str, **data) -> bool:
        # Calls guards only, no other hooks, never raises InvalidTransition/GuardRejected
        event = Event(name=event_name, source=self.state, target='', data=data)

        candidates = []
        for t in self.transitions:
            if t.event == event_name:
                source_matches = False
                if isinstance(t.source, str): 
                    if t.source == self.state: source_matches = True
                elif isinstance(t.source, (list, tuple)): 
                    if self.state in t.source: source_matches = True
                elif t.source == '*':
                    source_matches = True

                if source_matches:
                    candidates.append(t)

        if not candidates: 
            return False

        for t in candidates:
            if t.guard is None:
                return True
            try:
                # Rule: Guards must not have side effects
                if t.guard(self, event): 
                    return True
            except MachineError: 
                # If guard raises an exception, treat as rejected for can_fire
                pass

        return False

    def available_events(self) -> List[str]:
        # Sorted, de-duplicated names of events that have at least one transition from the current state, ignoring guards.
        available = set()
        for t in self.transitions:
            source_matches = False
            if isinstance(t.source, str) and t.source == self.state: 
                source_matches = True
            elif isinstance(t.source, (list, tuple)) and self.state in t.source: 
                source_matches = True
            elif t.source == '*':
                source_matches = True

            if source_matches:
                available.add(t.event)

        return sorted(list(available))

    def on_transition(self, listener: Any):
        # Adds a listener
        self._listeners.append(listener)

    def reset(self):
        # Sets state back to initial and clears history. Runs no hooks.
        self.state = self.initial_state_name
        self.history.clear()
    def can_fire(self, event: str, **data) -> bool:
        """Checks if a transition for the given event would be taken without executing it.
        Only calls guards; does not raise InvalidTransition or GuardRejected.
        """
        # 1. Find candidates
        candidates = [t for t in self.transitions if t.event == event and 
                      (t.source == self.state or t.source == '*')] 

        if not candidates:
            return False

        # 2. Evaluate guards
        for t in candidates:
            guard = t.guard
            if guard is None:
                return True
            try:
                # Guard must not have side effects
                if guard(self, Event(t.event, t.source, t.target, data)):
                    return True
            except Exception as e:
                # If guard fails due to side effects, we treat it as failed/rejected for safety
                # Though the spec implies side effects shouldn't happen, we catch it.
                continue

        return False

    def available_events(self) -> list[str]:
        """Returns sorted, de-duplicated names of events that have at least one transition from the current state.
        """
        events = set()
        for t in self.transitions:
            if t.source == self.state or t.source == '*':
                events.add(t.event)
        return sorted(list(events))

    def on_transition(self, listener):
        """Adds a listener function to be called after every successful transition.
        Listener signature: listener(source: str, event: str, target: str)
        """
        self._listeners.append(listener)

    def reset(self):
        """Sets state back to initial and clears history. Runs no hooks.
        """
        self.state = self.initial_state_name
        self.history.clear()

