        self.catalog = catalog
        self.clock = clock

        # State Management
        self._next_loan_id = 1

        # {loan_id: Loan object}
        self._active_loans: Dict[int, Loan] = {}
        self._returned_loans: Dict[int, Loan] = {}

        # {isbn: list[waiting_hold_position] where position is 1-based index in the queue}
        self._waiting_holds: Dict[str, List[str]] = {}

        # {isbn: list[ready_hold_data], data = (member_id, deadline)}
        self._ready_holds: Dict[str, List[Tuple[str, date]]] = {}

