        """Calls the clock function to get today's date."""
        return self.clock()

    def _apply_holds_expiry(self, today: date) -> None:
        """Applies the expiry logic for ready holds at the start of the day.
        This is the 'job run at the start of every day' logic."""
        expired_holds = []

        # Check all ISBNs for ready holds that have expired
        for isbn, ready_holds in self._ready_holds.items():
            new_ready_holds = []
            for i, (member_id, deadline) in enumerate(ready_holds):
                if deadline < today:
                    # Hold expired. Pass copy on.
                    expired_holds.append((isbn, member_id, deadline, i))
                else:
                    new_ready_holds.append((member_id, deadline))
            self._ready_holds[isbn] = new_ready_holds

        # Process expired holds sequentially to ensure correct passing of copies
        # We must process them in the order they were ready/set aside to maintain FIFO for the copy.
