def normalize_cell_name(name: str) -> str:
    """Converts a cell name (e.g., 'b7') to upper case ('B7') and validates it.
    """
    name = name.upper()
    if not name or not name[0].isalpha():
        raise FormulaError("Invalid cell name format.")

    col_str = ""
    row_str = ""
    i = 0
    while i < len(name) and name[i].isalpha():
        col_str += name[i]
        i += 1

    row_str = name[i:]

    # Column validation (A-Z)
    if len(col_str) > 26: # Though we only support up to Z
        raise FormulaError("Column name exceeds supported range.")

    # Row validation (1-999, no leading zeros unless it's '0' which is invalid)
    if not row_str.isdigit():
        raise FormulaError("Invalid row number format.")

    row_num = int(row_str)
    if not (1 <= row_num <= 999):
        raise FormulaError("Row number out of bounds (1-999).")

    # Check for leading zero if row_str has more than one digit
    if len(row_str) > 1 and row_str.startswith('0'):
        raise FormulaError("Row number cannot have leading zeros.")

    return name

