                node = BinaryOpNode(node, '*', right)
            elif op_type == 'DIV':
                node = BinaryOpNode(node, '/', right)
        return node

    # unary  := (+ | -) unary | number | ref | ( expr )
    def parse_unary(self) -> object:
        token = self.current_token()

        # Handle unary +/-
        if token.type == 'PLUS' or token.type == 'MINUS':
            op = self.advance().value
            # Unary operation binds tighter, so we recursively call parse_unary
            # (which handles the rest of the unary structure)
            operand = self.parse_unary()
            return UnaryOpNode(op, operand)

        # Handle parenthesized expression
        elif token.type == 'LPAREN':
            self.advance() # Consume '('
            node = self.parse_expr()
            self.eat('RPAREN') # Consume ')'
            return node

        # Handle number
        elif token.type == 'NUMBER':
            self.advance()
            try:
                # Determine if it's an int or float
                value_str = token.value
                if '.' in value_str:
                    return NumberNode(float(value_str))
                else:
                    return NumberNode(int(value_str))
            except ValueError:
                # Should not happen if tokenization is correct, but good practice
                raise FormulaError("Internal parsing error processing number.")

        # Handle reference
        elif token.type == 'REF':
            self.advance()
            # Validation of reference (bounds checking, format) must occur here
            try:
                # Normalize and validate ensures format and bounds are correct
                # It raises FormulaError if invalid
                normalized_name = normalize_cell_name(token.value)
                return RefNode(normalized_name)
            except FormulaError as e:
                # Re-raise validation errors
                raise e

        else:
            raise FormulaError(f"Unexpected token in unary position: {token.type} ({token.value})")

    def parse(self) -> object:
        if not self.tokens or len(self.tokens) == 1 and self.tokens[0].type == 'EOF':
            raise FormulaError("Empty formula provided.")

        ast = self.parse_expr()

        # After parsing the main expression, check if there are leftover tokens
        if self.current_token().type != 'EOF':
            raise FormulaError(f"Unexpected token after formula completion: {self.current_token().value} ({self.current_token().type})")

        return ast

# --- Public API Function --- 

def parse_formula(source: str) -> object:
    """Parses the text after '=' into an Abstract Syntax Tree (AST).
    Raises FormulaError for grammar violations or out-of-bounds references.
    """
    if not source.strip():
        raise FormulaError("Empty formula provided after '='.")

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

# =============================================================================
# IMPLEMENTATION START: references and evaluate
# =============================================================================

def references(tree: object) -> set[str]:
    """Returns the set of uppercase cell names the formula refers to.

    This function traverses the AST and collects the names from all RefNode instances.
    """
    referred_names = set()

    def traverse(node: object):
        if isinstance(node, RefNode):
            referred_names.add(node.name)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, NumberNode):
            pass # Numbers don't refer to cells
        else:
            # Handles cases like parenthesized expressions (where node is the result of parse_expr)
            # We assume the structure guarantees that only known types are encountered during recursion
            pass

    traverse(tree)
    return referred_names

# Helper functions for evaluation logic
def _is_error(value: object) -> bool:
    return isinstance(value, ErrorValue)

def _get_numeric_value(value: object) -> float | int | None:
    """Extracts numeric value if possible, otherwise returns None.
    Returns None if the value is text or an error.
    """
    if isinstance(value, (int, float)):
        return value
    return None

def _apply_binary_op(left_val: object, op: str, right_val: object) -> object:
    # --- Error Propagation (Rule 3) ---
    left_is_err = _is_error(left_val)
    right_is_err = _is_error(right_val)

    if left_is_err and right_is_err:
        return left_val # Left one if both are errors
    if left_is_err:
        return left_val
    if right_is_err:
        return right_val

    # --- Text Check (Rule 3) ---
    left_is_text = isinstance(left_val, str) and not left_val.startswith(('#ERROR!', '#CYCLE!'))
    right_is_text = isinstance(right_val, str) and not right_val.startswith(('#ERROR!', '#CYCLE!'))

    if left_is_text or right_is_text: 
        # If either operand is non-error text, result is #ERROR! unless it's addition/subtraction
        if op in ('*', '/'):
            return ERROR_CALCULATION
        # For +/-, text addition is not defined to be text, so it results in #ERROR!
        return ERROR_CALCULATION 

    # At this point, both values are numbers or one is 0 (from None reference)
    left_num = _get_numeric_value(left_val)
    right_num = _get_numeric_value(right_val)

    # This should ideally not happen if text checking is correct, but acts as a safeguard
    if left_num is None or right_num is None: 
        return ERROR_CALCULATION 

    # --- Arithmetic Operations (Rule 4) ---
    if op == '+':
        return left_num + right_num
    elif op == '-':
        return left_num - right_num
    elif op == '*':
        return left_num * right_num
    elif op == '/':
        if right_num == 0:
            return ERROR_CALCULATION
        return left_num / right_num

    # Should be unreachable
    return ERROR_CALCULATION

def _apply_unary_op(op: str, operand_val: object) -> object:
    # Error propagation is handled implicitly if operand_val is an error
    if _is_error(operand_val):
        return operand_val

    if op == '+':
        # Unary + does nothing, but we must return the value type correctly
        return operand_val
    elif op == '-':
        # Unary minus
        if isinstance(operand_val, (int, float)): 
            return -operand_val
        elif isinstance(operand_val, str): 
            # If operand is text (and not an error string), unary minus results in #ERROR!
            return ERROR_CALCULATION
        # If operand is None (empty), it acts like 0 -> -0 = 0
        elif operand_val is None: 
            return 0
        else: # Should be caught by error check above
            return ERROR_CALCULATION

    return ERROR_CALCULATION # Safety

# --- Main Evaluation Function ---

def evaluate(tree: object, lookup: callable) -> ErrorValue | int | float | str:
    """Computes the formula's value based on the tree and cell lookup function.
    """

    def resolve_reference(ref_node: RefNode) -> object:
        name = ref_node.name
        cell_value = lookup(name) # Returns None for empty, or value

        if cell_value is None: 
            # Rule 2: Empty cell gives 0 for calculation purposes
            return 0 

        if isinstance(cell_value, str) and not cell_value.startswith(('#ERROR!', '#CYCLE!')):
            # Rule 2: If the cell content is text, and this is a single reference, return text unchanged.
            # We must return it as string type here, not a numeric/error type.
            # This case is handled specially in the main evaluation logic, but we signal the raw string here.
            return cell_value 

        # Return the value if it's a number or an ErrorValue
        return cell_value

    def evaluate_node(node: object) -> object:
        # 1. NumberNode
        if isinstance(node, NumberNode):
            return node.value

        # 2. RefNode
        elif isinstance(node, RefNode):
            return resolve_reference(node)

        # 3. BinaryOpNode
        elif isinstance(node, BinaryOpNode):
            left_val = evaluate_node(node.left)
            right_val = evaluate_node(node.right)
            return _apply_binary_op(left_val, node.op, right_val)

        # 4. UnaryOpNode
        elif isinstance(node, UnaryOpNode):
            operand_val = evaluate_node(node.operand)
            return _apply_unary_op(node.op, operand_val)

        else:
            # Should not happen if AST is well-formed
            return ERROR_CALCULATION

    final_result = evaluate_node(tree)

    # Post-processing for single reference case (Rule 2 exception)
    if isinstance(tree, RefNode) and isinstance(final_result, str) and not final_result.startswith(('#ERROR!', '#CYCLE!')):
        # If the whole formula was just a reference to a text cell, return the string.
        return final_result

    # Final type conversion for consistency if result is a number
    if isinstance(final_result, float) and final_result.is_integer():
        return int(final_result)

    return final_result

from typing import Dict, Set, Iterable

class DependencyGraph:
    """Records dependencies between cells in the spreadsheet.

    A cell's precedents are the cells its formula refers to.
    Dependents are the cells that refer to it.
    """
    def __init__(self):
        # cell_name -> set of cells it refers to (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # cell_name -> set of cells that refer to it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replaces cell's precedents with the given iterable of names."""
        # Clear old dependencies for this cell
        old_precedents = self._precedents.get(cell, set())

        # 1. Remove cell from all old dependent sets
        for old_prec in old_precedents:
            if old_prec in self._dependents:
                self._dependents[old_prec].discard(cell)

        # Set new precedents
        new_precedents = set(precedents)
        self._precedents[cell] = new_precedents

        # 2. Update dependent sets for new precedents
        for new_prec in new_precedents:
            if new_prec not in self._dependents:
                self._dependents[new_prec] = set()
            self._dependents[new_prec].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct precedents (cells this cell refers to)."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct dependents (cells that refer to this cell)."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to 'cell' directly or through other cells.
        Includes 'cell' itself if it is on a cycle."""
        queue: Iterable[str] = [cell]
        visited: Set[str] = {cell}
        all_deps: Set[str] = {cell}

        while queue:
            current = queue.pop(0)

            for dependent in self._dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    all_deps.add(dependent)
                    queue.append(dependent)

        return all_deps

    def cycle_cells(self) -> Set[str]:
        """Returns every cell that lies on a cycle (a cell from which following precedents leads back to itself)."""
        all_cells = set(self._precedents.keys())

        # Helper for DFS cycle detection
        def dfs_cycle_check(cell: str, visited_path: Set[str], visited_final: Set[str]) -> Set[str]:
            """Performs DFS starting from cell to detect cycles.
            Returns the set of cells involved in a cycle found starting from this path.
            """
            if cell in visited_path:
                # Cycle detected
                return {cell}
            if cell in visited_final:
                # Already processed and confirmed not part of a cycle in a previous run
                return set()

            visited_path.add(cell)
            cycle_nodes = set()

            for precedent in self._precedents.get(cell, set()):
                if precedent not in all_cells: # Ignore external/unknown references if any
                    continue

                # Check if this precedent leads to a cycle
                sub_cycle = dfs_cycle_check(precedent, visited_path.copy(), visited_final)

                if sub_cycle:
                    # If a cycle was found downstream, this cell is part of it
                    cycle_nodes.add(cell)
                    cycle_nodes.update(sub_cycle)

            # Finished exploring all paths from this cell; mark as finalized
            visited_final.add(cell)
            visited_path.remove(cell) # Backtrack
            return cycle_nodes

        temp_cycles: Set[str] = set()
        visited_final: Set[str] = set()

        # Iterate over all cells to catch disconnected components
        for cell in all_cells:
            if cell not in visited_final:
                # We pass a fresh set for visited_path for each top-level call
                new_cycles = dfs_cycle_check(cell, set(), visited_final)
                temp_cycles.update(new_cycles)

        return temp_cycles

