from typing import Set, Dict, Iterable

class DependencyGraph:
    """Records dependencies between cells for efficient recalculation."""
    def __init__(self):
        # Precedents: cell -> set of cells it refers to (dependencies)
        self._precedents: Dict[str, Set[str]] = {}
        # Dependents: cell -> set of cells that refer to it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replaces cell's precedents with the given iterable of names."""
        if cell not in self._precedents:
            self._precedents[cell] = set()

        new_precedents = set(precedents)
        old_precedents = self._precedents[cell]

        # 1. Update dependents based on old precedents
        for old_dep in old_precedents:
            if old_dep in self._dependents:
                self._dependents[old_dep].discard(cell)

        # 2. Set new precedents and update dependents
        self._precedents[cell] = new_precedents
        for new_dep in new_precedents:
            if new_dep not in self._dependents:
                self._dependents[new_dep] = set()
            self._dependents[new_dep].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct precedents (dependencies) of a cell."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct dependents of a cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to 'cell' directly or through other cells. 
        Includes 'cell' itself if it is part of a cycle."""
        queue = list(self.dependents.get(cell, set()))
        visited = set(self.dependents.get(cell, set()))
        all_d = set(self.dependents.get(cell, set()))

        while queue:
            current = queue.pop(0)
            if current not in all_d:
                all_d.add(current)
                # Add current's dependents to the queue
                for next_dep in self._dependents.get(current, set()):
                    if next_dep not in visited:
                        visited.add(next_dep)
                        queue.append(next_dep)

        # Check for cycle: if cell depends on itself (directly or indirectly)
