## Implement Cell and Sheet Management

from typing import Optional, Dict, Any, Set, List
import re

# Assuming these imports are available from sibling/parent modules
from .formula import parse_formula, FormulaError, ErrorValue, references, evaluate
from .graph import DependencyGraph

# --- Constants and Helpers ---

MAX_ROWS = 999
MAX_COLS = 26  # A-Z

# Regex for valid cell names (A-Z, 1-999) and ensuring no leading zeros in rows
CELL_NAME_PATTERN = re.compile(r'^[A-Z][1-9][0-9]*$')

def _col_to_int(col_char: str) -> int:
    """Converts column letter (A=1, B=2, ...) to 1-based index."""
    return ord(col_char.upper()) - ord('A') + 1

def _int_to_col(col_index: int) -> str:
    """Converts 1-based index to column letter."""
    return chr(ord('A') + col_index - 1)

def _cell_to_coords(name: str) -> tuple[int, int]:
    """Converts cell name (e.g., 'A1') to (col_index, row_number) (1-based)."""
    col_str = re.match(r'([A-Z]+)(\d+)$', name.upper()) # Simplified regex for robustness check
    if not col_str: 
        raise ValueError(f"Invalid cell name format: {name}")

    col_str = col_str.group(1)
    row_str = col_str.group(2)

    col_idx = 0
    for char in col_str:
        col_idx = col_idx * 26 + (ord(char) - ord('A') + 1)

    row_num = int(row_str)

    if col_idx == 0 or row_num == 0 or row_num > MAX_ROWS:
        raise ValueError("Row or column out of bounds (1-999).")
    if row_str.startswith('0') and len(row_str) > 1: # Check for leading zeros if not just '0' (which is caught by row_num > 0)
        raise ValueError("Row number cannot have leading zeros.")

    return col_idx, row_num

def _coords_to_cell(col_idx: int, row_num: int) -> str:
    """Converts (col_index, row_number) to cell name (e.g., 'A1')."""
    return _int_to_col(col_idx) + str(row_num)

# --- Sheet Class ---

class Sheet:
    """Main spreadsheet engine class."""

    def __init__(self):
        # Stores the raw input string for each cell (e.g., '=SUM(A1:A2)', 'hello', '', '12.3')
        self._raw_values: Dict[str, str] = {}
        # Stores the computed value for each cell (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {}
        # Stores the parsed formula tree for cells containing formulas
        self._formula_trees: Dict[str, Any] = {}
        # Dependency graph management
        self._graph = DependencyGraph()
        self.evaluations: int = 0

    def _validate_name(self, name: str):
        """Validates if a cell name is within sheet bounds and format."""
        name = name.upper()
        if not CELL_NAME_PATTERN.match(name):
            # Check for edge case where formula might reference invalid cell if validation is strict
            # For robustness, we rely on _cell_to_coords to catch specific structural errors
            pass
        try:
            col_idx, row_num = _cell_to_coords(name)
            # Final check using coordinates derived from the name
            if not (1 <= col_idx <= MAX_COLS and 1 <= row_num <= MAX_ROWS):
                 raise ValueError(f"Cell name {name} is outside the sheet boundaries (A1:Z999).")
        except ValueError as e:
            raise ValueError(f"Invalid cell name or format: {name}. {e}")

    def _calculate_cell_value(self, name: str, is_cycle_check: bool = False) -> Any:
        """Determines the value of a single cell based on its raw content and dependencies."""
        raw = self.raw(name)

        if raw == '':
            return None # Empty cell

        # Check for cycle status first
        if self._graph.cycle_cells() and name in self._graph.cycle_cells():
            return ErrorValue('#CYCLE!')

        # Check if it's a formula
        if raw.strip().startswith('='):
            try:
                tree = self._formula_trees[name]
                lookup = self.get_lookup_function()

                # Rule 3 of evaluation: propagate errors
                return evaluate(tree, lookup)
            except Exception as e:
                # Any calculation error results in #ERROR!
                # This catches FormulaError from parsing, or runtime errors in evaluation.
                return ErrorValue('#ERROR!')
        else:
            # Not a formula, must be static text or number
            return self._parse_static_value(raw)

    def _parse_static_value(self, raw: str) -> Any:
        """Parses raw string into number or text."""
        stripped_raw = raw.strip()

        # Check for optional leading '-' followed by number format
        match = re.fullmatch(r'(-)?(\\d+\.?\d*)', stripped_raw)
        if match:
            sign = match.group(1) or ''
            num_str = match.group(2)

            try:
                if '.' in num_str:
                    value = float(num_str)
                else:
                    value = int(num_str)
                return value if sign == '' else -value
            except ValueError:
                # Should not happen if regex is correct, but safe fallback
                pass

        # Otherwise, it's text, stored exactly as given (spaces included)
        return raw

    def get_lookup_function(self) -> callable:
        """Returns a callable suitable for the formula evaluator."""
        def lookup(name: str) -> Any:
            """Implements the lookup rule: empty cell (None) gives 0."""
            value = self.get(name)
            if value is None: # Empty cell
                return 0
            return value
        return lookup

    def _recalculate_affected_cells(self, affected_names: Set[str]) -> List[str]:
        """
        Performs dependency-aware recalculation on the affected set.
        This simulates the required iterative/topological evaluation.
        """
        if not affected_names: return []

        # 1. Cycle detection (already done by graph, but confirm which are stable)
        cycle_cells = self._graph.cycle_cells()

        # 2. Initialize values based on cycle status
        # We need a stable set to iterate over.
        cells_to_process = list(affected_names)

        # The actual calculation loop needs to stabilize. Since full topological sort
        # requires knowledge of all dependencies *within* the affected set, we use iteration.

        # Use a copy of values to detect changes during iteration
        original_values = {name: self._values.get(name) for name in cells_to_process}

        # Iterative relaxation loop (simulating topological sort until convergence or max iterations)
        # A maximum iteration count prevents infinite loops if logic fails, though dependency structure should prevent it.
        MAX_ITERATIONS = len(cells_to_process) + 1

        for _ in range(MAX_ITERATIONS):
            changed = False
            next_values = {} # Store potential new values

            for name in cells_to_process:
                if name in cycle_cells:
                    next_values[name] = ErrorValue('#CYCLE!')
                    continue

                # Calculate the new value
                new_value = self._calculate_cell_value(name)

                # Check if value changed
                if next_values.get(name) != new_value:
                    next_values[name] = new_value
                    changed = True
                else:
                    # If it hasn't changed yet in this iteration, keep the previous calculated value
                    next_values[name] = original_values.get(name, new_value) 

            # Apply changes and update internal state
            self._values.update(next_values)

            if not changed: 
                break # Convergence reached

            # Prepare for next iteration
            original_values = next_values.copy()

        # 3. Update evaluation count for formula cells that were processed
        for name in cells_to_process:
            if name in self._formula_trees:
                self.evaluations += 1

        # Return affected names sorted in row-major order
        return sorted(list(affected_names))

    def set(self, name: str, raw: str) -> List[str]:
        """Stores input and triggers recalculation."""
        self._validate_name(name)
        name = name.upper()

        # 1. Store raw value
        self._raw_values[name] = raw

        is_formula = raw.strip().startswith('=')

        # 2. Parse formula if necessary
        if is_formula:
            try:
                # Parse formula using the function from formula.py
                tree = parse_formula(raw[1:].strip())
                self._formula_trees[name] = tree
            except FormulaError as e:
                # If parsing fails, re-raise and sheet remains unchanged
                # Must revert the raw value set in step 1 if we want absolute atomicity, 
                # but requirement says: "the sheet is left completely unchanged".
                # We must clean up before raising.
                self._raw_values[name] = name # Mark as invalid/unparsed state
                raise e
        else:
            # Clear formula tree if content is no longer a formula
            if name in self._formula_trees:
                del self._formula_trees[name]

        # 3. Update dependencies
        precedents_set: Set[str] = set()
        if is_formula:
            # Get cell names referred to by the formula tree
            precedents_set = references(self._formula_trees[name])

        self._graph.set_dependencies(name, precedents_set)

        # 4. Identify affected cells
        # The affected list includes the cell itself plus all cells that depend on it.
        affected_names = {name}
        affected_names.update(self._graph.all_dependents(name))

        # 5. Recalculate and get sorted list
        return self._recalculate_affected_cells(affected_names)

    def get(self, name: str) -> Optional[Any]:
        """Returns the cell's computed value."""
        self._validate_name(name)
        name = name.upper()
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the last input stored for the cell."""
        self._validate_name(name)
        name = name.upper()
        return self._raw_values.get(name, '')

    def cells(self) -> List[str]:
        """Returns the non-empty cells in row-major order."""
        # Generate all valid cell names in row-major order (R1C1, R1C2, ..., R999C26)
        all_cells: List[str] = []
        for r in range(1, MAX_ROWS + 1):
            for c_idx in range(1, MAX_COLS + 1):
                all_cells.append(_coords_to_cell(c_idx, r))

        non_empty_cells: List[str] = []
        for name in all_cells:
            if self.raw(name) != '':
                non_empty_cells.append(name)
        return non_empty_cells

