class BinaryOpNode(FormulaNode):
    """Represents binary operations (+, -, *, /)."""
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op
        self.right = right

    def __repr__(self):
        return f"BinaryOpNode({repr(self.left)}, '{self.op}', {repr(self.right)})"

class UnaryOpNode(FormulaNode):
    """Represents unary operations (+, -)."""
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryOpNode('{self.op}', {repr(self.operand)})"

class ParenthesisNode(FormulaNode):
    """Represents grouped expression (expr)."""
