import re
from typing import Union, List, Set, Dict, Any, Callable

# --- Error Handling ---

class FormulaError(ValueError):
    """Raised for syntax errors or invalid formula inputs."""
    pass

class ErrorValue(str):
    """Represents a specific calculation error in a cell."""
    def __init__(self, message: str):
        super().__init__(message)
        self.is_error = True

    def __eq__(self, other):
        if isinstance(other, ErrorValue): # Allow comparison between two error values
            return self.args == other.args
        return super().__eq__(other)

    def __str__(self):
        return self.args

# --- AST Node Definitions ---

class ASTNode:
    """Base class for AST nodes."""
    pass

class NumberLiteral(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class Ref(ASTNode):
    def __init__(self, name: str):
        self.name = name

class BinaryOp(ASTNode):
    def __init__(self, left: ASTNode, op: str, right: ASTNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

class UnaryOp(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+', '-'
        self.operand = operand

class ParenthesizedExpr(ASTNode):
    def __init__(self, expr: ASTNode):
        self.expr = expr

# --- Tokenization ---

# Regex for numbers (digits [. digits])
NUMBER_RE = r'  [0-9]+(?:\.[0-9]+)?  ' 

# Regex for references (letters digits, case-insensitive)
REF_RE = r' [a-zA-Z]+[0-9]+ ' 

# Regex for operators and parentheses
OPERATOR_RE = r'[+\-*/()]'

TOKEN_SPEC = [ 
    ('NUMBER', r' [0-9]+(?:  [0-9]+ )? '),  # Number (Handles integers and floats)
    ('REF', r'[a-zA-Z]+[0-9]+'),              # Reference
    ('OP', r'[+\-*/()]'),                     # Operators and parentheses
    ('SKIP', r'[ \t]+'),                       # Whitespace
    ('MISMATCH', r'.')                          # Any other character
]

TOKEN_REGEX = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPEC)

class Token:
    def __init__(self, type: str, value: str): 
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, '{self.value}')"

def tokenize(source: str) -> List[Token]:
    """Converts formula string into a list of tokens."""
    tokens = []
    for mo in re.finditer(TOKEN_REGEX, source, re.IGNORECASE):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Unexpected character: {value}")

        if kind == 'NUMBER':
            tokens.append(Token('NUMBER', value))
        elif kind == 'REF':
            tokens.append(Token('REF', value.upper())) # References are returned in upper case
        elif kind == 'OP':
            tokens.append(Token('OP', value))

    return tokens

# --- Parser (Recursive Descent) ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token: 
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token('EOF', '')

    def advance(self):
        self.pos += 1

    def eat(self, token_type: str, expected_value: str = None):
        token = self.current_token()
        if token.type != token_type or (expected_value and token.value != expected_value):
            raise FormulaError(f"Syntax Error: Expected {token_type}{' ('+ expected_value+')' if expected_value else ''}, but got {token.type} ('{token.value}')")
        self.advance()

    def parse(self) -> ASTNode:
        # The grammar starts with expr
        tree = self.expr()
        if self.current_token().type != 'EOF':
            raise FormulaError("Syntax Error: Unexpected token after expression end")
        return tree

    def expr(self) -> ASTNode:
        # expr   := term {(+ | -) term} (Left associative)
        node = self.term()
        while self.current_token().type == 'OP' and self.current_token().value in ('+', '-'):
            op = self.current_token().value
            self.advance()
            right = self.term()
            if isinstance(node, BinaryOp) and node.op in ('+', '-'):
                # Combine left-associatively
                node = BinaryOp(node, op, right)
            else:
                node = BinaryOp(node, op, right)
        return node

    def term(self) -> ASTNode:
        # term   := unary {(* | /) unary} (Left associative)
        node = self.unary()
        while self.current_token().type == 'OP' and self.current_token().value in ('*', '/'):
            op = self.current_token().value
            self.advance()
            right = self.unary()
            # Combine left-associatively
            node = BinaryOp(node, op, right)
        return node

    def unary(self) -> ASTNode:
        # unary  := (+ | -) unary | number | ref | ( expr )
        token = self.current_token()

        if token.type == 'OP' and token.value in ('+', '-'):
            op = token.value
            self.advance()
            # Unary operator binds tighter than binary, so recursively call unary
            return UnaryOp(op, self.unary())
        elif token.type == 'NUMBER':
            self.advance()
            return NumberLiteral(float(token.value) if '.' in token.value else int(token.value))
        elif token.type == 'REF':
            self.advance()
            return Ref(token.value)
        elif token.type == 'OP' and token.value == '(': 
            self.advance() # Consume '(' 
            node = self.expr()
            self.eat('OP', ')') # Consume ')'
            return ParenthesizedExpr(node)
        else:
            raise FormulaError(f"Syntax Error: Expected number, reference, unary operator, or '(', got {token.type} ('{token.value}')")

# --- Public API Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' into a syntax tree."""
    if not source or not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    try:
        tokens = tokenize(source)
        parser = Parser(tokens)
        return parser.parse()
    except FormulaError as e:
        # Re-raise parsing errors
        raise e
    except Exception as e:
        # Catch unexpected errors during tokenizing/parsing and wrap them
        raise FormulaError(f"Parsing failed: {e}")


def references(tree: ASTNode) -> Set[str]:
    """Returns the upper-case names of the cells the formula refers to."""
    refs: Set[str] = set()

    def traverse(node: ASTNode):
        if isinstance(node, Ref):
            refs.add(node.name)
        elif isinstance(node, BinaryOp):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOp):
            traverse(node.operand)
        elif isinstance(node, ParenthesizedExpr):
            traverse(node.expr)
        elif isinstance(node, NumberLiteral):
            pass # Numbers don't reference cells

    traverse(tree)
    return refs


# --- Evaluation Logic ---

# Define types for clarity during evaluation
CellType = Union[int, float, str, None, ErrorValue]
LookupFunc = Callable[[str], CellType]

def _apply_binary_op(op: str, left_val: CellType, right_val: CellType) -> CellType:
    """Applies binary arithmetic or handles error/text propagation."""

    # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
    if isinstance(left_val, ErrorValue):
        return left_val
    if isinstance(right_val, ErrorValue):
        return right_val

    # Rule 3: If an operand is text, the result is #ERROR!.
    if isinstance(left_val, str) and not left_val.startswith('#'):
        return ErrorValue("#ERROR!")
    if isinstance(right_val, str) and not right_val.startswith('#'):
        return ErrorValue("#ERROR!")

    # Arithmetic operations (must be numeric or None)

    # Handle None (empty cell value) as 0 for arithmetic, as per Rule 2 context.
    def numeric_conversion(val: CellType) -> Union[int, float, None]:
        if val is None: return 0
        if isinstance(val, (int, float)): return val
        # This path should theoretically be caught by the text checks above if not None
        return None

    l_num = numeric_conversion(left_val)
    r_num = numeric_conversion(right_val)

    if l_num is None or r_num is None:
        # Should not happen if error/text checks work, but as a safeguard:
        return ErrorValue("#ERROR!")

    if op == '+':
        return left_val + right_val
    elif op == '-':
        return left_val - right_val
    elif op == '*':
        return left_val * right_val
    elif op == '/':
        if r_num == 0:
            return ErrorValue("#ERROR!") # Division by zero
        return l_num / r_num
    else:
        # Should be unreachable
        return ErrorValue("#ERROR!")


def evaluate(tree: ASTNode, lookup: LookupFunc) -> CellType:
    """Computes the formula's value given a lookup function for cell values."""

    if isinstance(tree, NumberLiteral):
        return tree.value

    elif isinstance(tree, Ref):
        # Rule 2: A reference gives the cell's value, except that an empty cell (None) gives 0.
        # A formula that is only a reference therefore returns text unchanged ('=A1' where 'A1' holds 'hi' gives 'hi').
        cell_value = lookup(tree.name)

        if cell_value is None:
            # Empty cell -> 0 for arithmetic context, but for single ref, return text unchanged.
            # Since 'evaluate' is called for a formula, if it's a single ref, we return the text representation if it's not numeric.
            # However, the rules state: 'A reference gives the cell's value, except that an empty cell (None) gives 0.'
            # And: 'A formula that is only a reference therefore returns text unchanged' if the cell holds text.
            # Let's interpret this: If it's just a ref, we check what the cell holds.
            # If it holds text, we return text. If it holds number/error, we return that.

            # For a single reference formula, the cell's value is what is returned.
            # If the cell is None, it acts like 0 in arithmetic, but if it's a single reference formula, we must return '0' or the original text if it was text.
            # Given the constraint: 'A formula that is only a reference therefore returns text unchanged', if A1=None, it has no text, so it must resolve to 0 if we follow the first rule.
            return 0

        if isinstance(cell_value, str) and not cell_value.startswith('#') and not isinstance(cell_value, ErrorValue):
            # Text unchanged
            return cell_value

        # Otherwise, return the actual value (number, error value)
        return cell_value

    elif isinstance(tree, BinaryOp):
        # Rule 3: Left-to-right evaluation
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)
        return _apply_binary_op(tree.op, left_val, right_val)

    elif isinstance(tree, UnaryOp):
        operand_val = evaluate(tree.operand, lookup)
        op = tree.op

        if isinstance(operand_val, ErrorValue):
            return operand_val # Propagate error

        if isinstance(operand_val, str) and not operand_val.startswith('#') and not isinstance(operand_val, ErrorValue):
            # Text cannot be unary operated on
            return ErrorValue("#ERROR!")

        # Arithmetic operations
        if op == '+':
            return operand_val + 0 if isinstance(operand_val, (int, float)) else operand_val # Handles None->0
        elif op == '-':
            return operand_val - 0 if isinstance(operand_val, (int, float)) else operand_val
        # Should not happen based on grammar
        return ErrorValue("#ERROR!")

    elif isinstance(tree, ParenthesizedExpr):
        return evaluate(tree.expr, lookup)

    else:
        raise FormulaError("Unknown AST Node Type during evaluation")
