from typing import Union, List, Dict, Any, Set

# --- Error Values and Types ---

class FormulaError(ValueError):
    """Raised for formula syntax errors or invalid references."""
    pass

class ErrorValue(str):
    """Represents a calculation error in a cell."""
    pass

# Define types for clarity
NumberLiteral = Union[int, float]
CellValue = Union[NumberLiteral, str, None, ErrorValue]

# --- Syntax Tree Nodes ---

class FormulaNode:
    """Base class for all formula nodes."""
    pass

class NumberNode(FormulaNode):
    """Represents a number literal."""
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self):
        return f"NumberNode({self.value})"

class ReferenceNode(FormulaNode):
    """Represents a cell reference (e.g., 'A1')."""
    def __init__(self, ref_name: str):
        self.ref_name = ref_name.upper() # Store uppercase

    def __repr__(self):
        return f"ReferenceNode('{self.ref_name}')"

class BinaryOpNode(FormulaNode):
    """Represents binary operations (+, -, *, /)."""
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op
        self.right = right

    def __repr__(self):
        return f"BinaryOpNode({repr(self.left)}, '{self.op}', {repr(self.right)})"

class UnaryOpNode(FormulaNode):
    """Represents unary operations (+, -)."""
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryOpNode('{self.op}', {repr(self.operand)})"

class ParenthesisNode(FormulaNode):
    """Represents grouped expression (expr)."""
    def __init__(self, expression: FormulaNode):
        self.expression = expression

    def __repr__(self):
        return f"ParenthesisNode({repr(self.expression)})"

# --- Parser Implementation (Simplified structure for demonstration) ---

class Parser:
    """A basic recursive descent parser for the formula grammar."""
    def __init__(self, source: str):
        self.source = source.strip()
        self.pos = 0
        self.tokens = self._tokenize(self.source)
        self.current_token_index = 0

    def _tokenize(self, source: str) -> List[str]:
        # This is a highly simplified tokenizer. A real implementation would be complex.
        # We split on whitespace and keep operators/parentheses intact if needed.
        import re
        # Pattern matches numbers (including floats), letters (for refs), operators, and parentheses.
        tokens = re.findall(r"[0-9]+(\.[0-9]+)?|([a-zA-Z]+)|[+\-*/()]", source)
        cleaned = []
        for t in tokens:
            # Flatten the tuple result from re.findall
            for item in t:
                if item: 
                    cleaned.append(item)
        return cleaned

    def _peek(self) -> str | None:
        if self.current_token_index < len(self.tokens):
            return self.tokens[self.current_token_index]
        return None

    def _consume(self, expected: str | None = None) -> str:
        token = self._peek()
        if token is None: 
            raise FormulaError("Unexpected end of expression.")
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but found '{token}'.")
        self.current_token_index += 1
        return token

    def parse(self) -> FormulaNode:
        if not self.source: 
            raise FormulaError("Empty formula input.")
        node = self._expr()
        if self._peek() is not None: 
            raise FormulaError("Unexpected trailing characters after expression.")
        return node

    # Grammar Rules (Simplified implementation logic)
    # expr   := term {(+ | -) term}
    def _expr(self) -> FormulaNode:
        node = self._term()
        while self._peek() in ['+', '-']:
            op = self._consume()
            right = self._term()
            node = BinaryOpNode(node, op, right)
        return node

    # term   := unary {(* | /) unary}
    def _term(self) -> FormulaNode:
        node = self._unary()
        while self._peek() in ['*', '/']:
            op = self._consume()
            right = self._unary()
            node = BinaryOpNode(node, op, right)
        return node

    # unary  := (+ | -) unary | number | ref | ( expr )
    def _unary(self) -> FormulaNode:
        token = self._peek()
        if token in ['+', '-']:
            op = self._consume()
            return UnaryOpNode(op, self._unary())

        if token and token.isdigit() or ('.' in token and token.replace('.', '', 1).isdigit()):
            self._consume()
            try:
                if '.' in token: 
                    return NumberNode(float(token))
                else: 
                    return NumberNode(int(token))
            except ValueError:
                 raise FormulaError(f"Invalid number format: {token}")
        elif token and token.isalpha():
            return self._ref()
        elif token == '(': 
            self._consume('(')
            node = self._expr()
            self._consume(')')
            return ParenthesisNode(node)
        else:
            raise FormulaError(f"Unexpected token in unary expression: {token}")

    def _ref(self) -> ReferenceNode:
        # Ref is letters digits, case-insensitive
        # A proper check would ensure it's only letters followed by digits.
        # We consume the word/number part until a non-reference character is found.
        import re
        match = re.match(r"([a-zA-Z]+)([0-9]+)", self._peek() + self._consume() + "")

        if match:
            ref_name = match.group(1).upper() + match.group(2)
            # Consume exactly the matched part from the source stream for simplicity here
            # In a real tokenizer, this would be cleaner.
            # Since we are using token list, we rely on the token being correctly parsed.
            # Assuming the tokenizer provided a combined string for a reference.
            return ReferenceNode(match.group(0).upper())
        else:
            # If the token is alphabetic but not followed by digits in the grammar sense
            self._consume()
            raise FormulaError(f"Invalid reference format: {self._peek() if self._peek() else 'EOF'}")


# Global function to expose parsing
def parse_formula(source: str) -> FormulaNode:
    """Parses the text after '=' into a syntax tree."""
    if not source:
        raise FormulaError("Formula source cannot be empty.")
    try:
        parser = Parser(source)
        return parser.parse()
    except FormulaError as e:
        raise e
    except Exception as e:
        # Catch parsing errors not explicitly handled as FormulaError
        raise FormulaError(f"General parsing error: {e}")


# --- Reference Extraction ---

def references(tree: FormulaNode) -> Set[str]:
    """Recursively finds all unique, upper-case cell references in the tree."""
    found_refs: Set[str] = set()

    if isinstance(tree, ReferenceNode):
        found_refs.add(tree.ref_name)
    elif isinstance(tree, BinaryOpNode):
        found_refs.update(references(tree.left))
        found_refs.update(references(tree.right))
    elif isinstance(tree, UnaryOpNode):
        found_refs.update(references(tree.operand))
    elif isinstance(tree, ParenthesisNode):
        found_refs.update(references(tree.expression))
    # NumberNode adds nothing

    return found_refs


# --- Evaluation Logic ---

# Forward declaration for type hinting lookup
LookupFunc = callable[[str], CellValue]

# Helper to handle error propagation
def propagate_error(val1: CellValue, val2: CellValue, op: str) -> CellValue:
    if isinstance(val1, ErrorValue) or isinstance(val2, ErrorValue):
        return val1 if isinstance(val1, ErrorValue) else val2
    return None # Should not happen if inputs are properly validated

def evaluate(tree: FormulaNode, lookup: LookupFunc) -> CellValue:
    """Computes the formula's value based on current cell values."""

    # 1. Handle base cases (Numbers and References)
    if isinstance(tree, NumberNode):
        return tree.value

    if isinstance(tree, ReferenceNode):
        name = tree.ref_name
        value = lookup(name)

        # Rule 2: Reference behavior
        if value is None: # Empty cell
            return 0
        if isinstance(value, str) and not isinstance(value, ErrorValue):
            # If the cell holds text, return the text unchanged (as per rule)
            return value 
        return value

    # 2. Handle Unary Operations
    if isinstance(tree, UnaryOpNode):
        operand_value = evaluate(tree.operand, lookup)
        if isinstance(operand_value, ErrorValue):
            return operand_value

        # Unary +/- only affects numbers if it's a literal or reference resulting in number
        if isinstance(operand_value, (int, float)):
            if tree.op == '+':
                return operand_value
            else: # '-'
                return -operand_value
        else: # Text or ErrorValue
            return ErrorValue('#ERROR!') # Text cannot be unary +/-ed

    # 3. Handle Binary Operations
    if isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)
        op = tree.op

        # Rule 3: Error propagation
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return propagate_error(left_val, right_val, op)

        # Rule 3: Text handling
        left_is_text = isinstance(left_val, str) and not isinstance(left_val, ErrorValue)
        right_is_text = isinstance(right_val, str) and not isinstance(right_val, ErrorValue)
        if left_is_text or right_is_text:
            return ErrorValue('#ERROR!')

        # Rule 4: Numerical operations
        l_num = left_val if isinstance(left_val, (int, float)) else 0 # Should be caught above, but for safety
        r_num = right_val if isinstance(right_val, (int, float)) else 0

        try:
            if op == '+':
                return l_num + r_num
            elif op == '-':
                return l_num - r_num
            elif op == '*':
                return l_num * r_num
            elif op == '/':
                if r_num == 0:
                    return ErrorValue('#ERROR!')
                return l_num / r_num
        except Exception:
            # Catch unexpected math errors
            return ErrorValue('#ERROR!')

    raise FormulaError("Unknown node type during evaluation.")

