# Helper function to convert cell name (e.g., 'B7') to (col_index, row_index)
def _parse_cell_name(name: str) -> tuple[int, int]:
    # Assumes name is already upper-cased and valid per spec
    import re
    match = re.match(r"([A-Z]{1,26})([1-9]{1,4})", name)
    if not match:
        raise ValueError(f"Invalid cell name format: {name}")

    col_str = match.group(1)
    row_str = match.group(2)

    # Column calculation (A=0, B=1, ..., Z=25, AA=26, ...)
    col_index = 0
    for char in col_str:
        col_index = col_index * 26 + (ord(char) - ord('A') + 1)
    col_index -= 1 # 0-indexed

    row_index = int(row_str) - 1 # 0-indexed

    if not (0 <= row_index <= MAX_ROWS - 1 and 0 <= col_index <= MAX_COLS - 1):
        raise ValueError(f"Cell name {name} is outside the sheet boundaries (1-999, A-Z).")

    return col_index, row_index

# Helper function to convert (col_index, row_index) to cell name (e.g., (1, 6) -> 'B7')
def _format_cell_name(col_index: int, row_index: int) -> str:
    if not (0 <= row_index <= MAX_ROWS - 1 and 0 <= col_index <= MAX_COLS - 1):
        raise ValueError("Coordinates are outside sheet boundaries.")

    # Row is 1-indexed
    row_str = str(row_index + 1)

    # Column calculation (0 -> 'A', 1 -> 'B', 26 -> 'AA')
    col_val = col_index + 1
    col_str = ""
    while col_val > 0:
        remainder = (col_val - 1) % 26
        col_str = chr(ord('A') + remainder) + col_str
        col_val = (col_val - 1) // 26

    return col_str + row_str

