        # Assumes name is valid (e.g., 'B7')
        col_part = name[:-len(str(int(name[len(name)-1:])))]
        row_part = int(name[-len(str(int(name[-1:]))):]) # Simplistic, assuming single digit row for quick sort key extraction if needed

        # A robust way is parsing to index, but for sorting keys, (row, col_ordinal) works.
        # Since the spec requires row-major: (Row Number, Column Index).
        # We must use the parsed indices.
        try:
