        if (len(match.group(1)) > 1 and match.group(1).startswith('0')) or \
           (len(match.group(2)) > 1 and match.group(2).startswith('0')) or \
           (len(match.group(3)) > 1 and match.group(3).startswith('0')):
            raise ValueError(f"Invalid version format: '{text}'. No leading zeros allowed unless the part is '0'.")

        self.major = major
        self.minor = minor
        self.patch = patch

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self.__lt__(other) or self.__eq__(other)

    def __ge__(self, other):
        return self.__gt__(other) or self.__eq__(other)

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

class Range:
    """Represents a version range constraint spec."""
    def __init__(self, spec: str):
        self.constraints: list[tuple[str, Version | None, Version | None]] = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        # Regex to capture constraint, operator, and version part
        # Handles *, ==V, !=V, >=V, <=V, >V, <V, ^V, ~V
        constraint_regex = re.compile(r"(\S+)(==|!=|>=|<=|>|<|\^|~)(\S+)")

        # Split by comma, ignoring whitespace around constraints
        constraints_list = [c.strip() for c in spec.split(',') if c.strip()]

        if not constraints_list:
            self.constraints.append(('', '*', None, None))
            return

        for constraint_str in constraints_list:
            match = constraint_regex.match(constraint_str)
            if not match:
                # Check for simple '*' constraint
                if constraint_str == "*":
                    self.constraints.append(('', '*', None, None))
                    continue
                # Handle malformed constraint or unknown operator
                raise ValueError(f"Invalid constraint format: '{constraint_str}' in range spec.")

            full_constraint, op, version_text = match.groups()

            try:
                version = Version(version_text)
            except ValueError as e:
                raise ValueError(f"Invalid version in range spec '{constraint_str}': {e}")

            # Normalize operators
            if op == "==":
                self.constraints.append((full_constraint, "==", version))
            elif op == "!=":
                self.constraints.append((full_constraint, "!=", version))
            elif op == ">=":
                self.constraints.append((full_constraint, ">=", version))
            elif op == "<":
                self.constraints.append((full_constraint, "<", version))
            elif op == "=": # Should not happen based on regex, but for safety
                 raise ValueError(f"Unknown operator in constraint: {op}")
            elif op == ">":
                self.constraints.append((full_constraint, ">", version))
            elif op == "<":
                self.constraints.append((full_constraint, "<", version))
            elif op == "^": # Caret operator
                # ^1.2.3 is >=1.2.3, <2.0.0. ^0.2.3 is >=0.2.3, <0.3.0. ^0.0.3 is >=0.0.3, <0.0.4. ^0.0.0 is >=0.0.0, <0.0.1.
                if version.major > 0:
                    # Standard caret: bump major version
                    next_major = version.major + 1
                    next_version = Version(f"{next_major}.0.0")
                    self.constraints.append((full_constraint, ">=", version))
                    self.constraints.append((full_constraint, "<", next_version))
                else:
                    # Pre-1.0.0: bump next non-zero part (minor or patch)
                    if version.minor > 0:
                        next_minor = version.minor + 1
                        next_version = Version(f"{version.major}.{next_minor}.0")
                        self.constraints.append((full_constraint, ">=", version))
                        self.constraints.append((full_constraint, "<", next_version))
                    elif version.patch > 0:
                        next_patch = version.patch + 1
                        next_version = Version(f"{version.major}.{version.minor}.{next_patch}")
                        self.constraints.append((full_constraint, ">=", version))
                        self.constraints.append((full_constraint, "<", next_version))
                    else: # 0.0.0
                        next_version = Version("0.0.1")
                        self.constraints.append((full_constraint, ">=", version))
                        self.constraints.append((full_constraint, "<", next_version))
            elif op == "~": # Tilde operator
                # ~1.2.3 is >=1.2.3, <1.3.0
                if version.major == 0 and version.minor == 0 and version.patch == 0:
                    # ~0.0.0 is >=0.0.0, <0.0.1
                    next_version = Version("0.0.1")
                    self.constraints.append((full_constraint, ">=", version))
                    self.constraints.append((full_constraint, "<", next_version))
                elif version.major == 0: # ~0.X.Y is >=0.X.Y, <0.(X+1).0
                    next_minor = version.minor + 1
                    next_version = Version(f"0.{next_minor}.0")
                    self.constraints.append((full_constraint, ">=", version))
                    self.constraints.append((full_constraint, "<", next_version))
                else: # ~X.Y.Z is >=X.Y.Z, <X.(Y+1).0
                    next_minor = version.minor + 1
                    next_version = Version(f"{version.major}.{next_minor}.0")
                    self.constraints.append((full_constraint, ">=", version))
                    self.constraints.append((full_constraint, "<", next_version))
            else:
                raise ValueError(f"Unknown operator '{op}' in constraint '{constraint_str}'")

    def contains(self, version: Version) -> bool:
        # A version satisfies the range if it satisfies ALL constraints
        for _, op, limit_version in self.constraints:
            if op == "*":
                continue

            if op == "==":
                if version != limit_version:
                    return False
            elif op == "!=":
                if version == limit_version:
                    return False
            elif op == ">=":
                if version < limit_version:
                    return False
            elif op == "<":
                if version >= limit_version:
                    return False
            elif op == ">":
                if version <= limit_version:
                    return False
            elif op == "=": # Should not happen
                return False
            elif op == "^":
                # Caret constraints are already decomposed into >= and < in _parse_spec
                # This case should ideally not be hit if decomposition is correct, but check defensively
                if version < limit_version: 
                    return False
                # Full logic for caret requires checking the specific boundary derived during parsing,
                # but since we decomposed it, checking >= and < for all decomposed parts is sufficient.
                pass # Handled by explicit >= and < constraints
            elif op == "~":
                # Tilde constraints are also decomposed into >= and <
                pass # Handled by explicit >= and < constraints

        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct the string representation from constraints for the required format
        parts = []

        # Collect unique constraints for string representation
        seen_constraints = set()

        for _, op, limit_version in self.constraints:
            # Use the original constraint string format if possible, or default to standard comparison
            # For simplicity and adherence to the requirement 'str(r) is the spec with all whitespace removed', 
            # we reconstruct the standard form using the stored operators and versions.

            if op == "*":
                parts.append("*" )
            elif op == "==":
                parts.append(f"=={limit_version.str()}" )
            elif op == "!=":
                parts.append(f"!={limit_version.str()}" )
            elif op == ">=":
                parts.append(f">={limit_version.str()}" )
            elif op == "<":
                parts.append(f"<{limit_version.str()}" )
            elif op == ">":
                parts.append(f">{limit_version.str()}" )
            elif op == "^":
                # Reconstruct caret based on the original parsing logic if possible, otherwise approximate
                parts.append(f"^{limit_version.str()}" )
            elif op == "~":
                parts.append(f"~{limit_version.str()}" )

        # Remove duplicates while maintaining order of appearance (though order doesn't strictly matter for the spec string)
        final_parts = []
        for part in parts:
            if part not in final_parts:
                final_parts.append(part.strip())

        return ",".join(final_parts)

