from typing import Dict, List, Optional
from resolve.versions import Version, Range
from collections import defaultdict

class PackageIndex:
    """
    Serves as the database for all available package versions and their dependencies.
    """
    def __init__(self):
        # Structure: {name: {version_object: {'requires': {dep_name: Range}}}} 
        self._releases: Dict[str, Dict[Version, Dict[str, Range]]] = defaultdict(dict)

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None) -> None:
        """Adds a release of a package.
        :param name: Package name.
        :param version_str: Version string (e.g., '1.2.3').
        :param requires: Dict mapping dependency names to range spec strings.
        :raises ValueError: If the package/version already exists or input is invalid.
        """
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string for {name}: {e}")

        if name in self._releases and version in self._releases[name]:
            raise ValueError(f"Package {name} version {version} already exists in the index.")

        dependency_ranges: Dict[str, Range] = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    dependency_ranges[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Invalid range spec '{spec_str}' for dependency '{dep_name}' in {name}@{version}: {e}")

        self._releases[name][version] = {"requires": dependency_ranges}

    def versions(self, name: str) -> List[Version]:
        """Returns a list of known Version objects for a package, newest first.
        """
        if name not in self._releases:
            return []

        # Sort by version tuple (major, minor, patch) descending
        return sorted(self._releases[name].keys(), reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns a dict mapping dependency names to their Range object for a specific release.
        :raises KeyError: If the package/version combination is not found.
        """
        if name not in self._releases or version not in self._releases[name]:
            raise KeyError(f"Package {name} version {version} not found in index.")
        return self._releases[name][version]["requires"]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict]]):
        """Builds an index from a dictionary structure.
        Data format: {name: {version_str: {dep: spec, ...}, ...}, ...}
        """
        index = cls()
        for name, versions_data in data.items():
            for version_str, requirements_data in versions_data.items():
                try:
                    version = Version(version_str)
                except ValueError as e:
                    raise ValueError(f"Data error: Invalid version string '{version_str}' for {name}: {e}")

                dependency_ranges: Dict[str, Range] = {}
                for dep_name, spec_str in requirements_data.items():
                    try:
                        dependency_ranges[dep_name] = Range(spec_str)
                    except ValueError as e:
                        raise ValueError(f"Data error: Invalid range spec '{spec_str}' for dependency '{dep_name}' in {name}@{version_str}: {e}")

                index._releases[name][version] = {"requires": dependency_ranges}
        return index

