        if not match:
            raise ValueError(f"Invalid version format: {text}")

        self.major = int(match.group(1))
        self.minor = int(match.group(2))
        self.patch = int(match.group(3))

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __repr__(self):
        return f"Version('{self.to_string()}')"

    def to_string(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __str__(self) -> str:
        return self.to_string()

@total_ordering
class Range:
    """Represents a package version range constraint."""

    OPERATORS = { 
        '==': lambda v, r: v == r, 
        '!=': lambda v, r: v != r, 
        '>=': lambda v, r: v >= r, 
        '<=': lambda v, r: v <= r, 
        '>': lambda v, r: v > r, 
        '<': lambda v, r: v < r
    }

    def __init__(self, spec: str):
        self.spec = spec.strip()
        self.constraints = []
        self._parse_spec()

    def _parse_spec(self):
        if not self.spec: 
            raise ValueError("Range specification cannot be empty.")

        # Split by comma, handling potential empty constraints
        raw_constraints = [c.strip() for c in self.spec.split(',')]

        for rc in raw_constraints:
            if not rc: 
                continue # Ignore empty constraints like '>=1.0.0,'

            # Handle '*' first
            if rc == '*':
                self.constraints.append({'op': 'wildcard'})
                continue

            # Handle explicit operators
            match_op = re.match(r"(==|!=|>=|<=|>|<)([0-9]+\.[0-9]+\.[0-9]+)", rc)
            if match_op:
                op_str, version_str = match_op.groups()
                version = Version(version_str)
                self.constraints.append({'op': op_str, 'version': version})
                continue

            # Handle caret (^) and tilde (~) prefixes
            match_prefix = re.match(r"([^0-9]+)([0-9]+\.[0-9]+\.[0-9]+)", rc)
            if match_prefix:
                prefix, version_str = match_prefix.groups()
                version = Version(version_str)

                if prefix == '^':
                    # ^1.2.3 is >=1.2.3, <2.0.0
                    # ^0.2.3 is >=0.2.3, <0.3.0
                    # ^0.0.3 is >=0.0.3, <0.0.4
                    # ^0.0.0 is >=0.0.0, <0.0.1
                    if version.major > 0:
                        upper_bound = Version(f"{version.major + 1}.0.0")
                        self.constraints.append({'op': '>=', 'version': version})
                        self.constraints.append({'op': '<', 'version': upper_bound})
                    else: # Major is 0
                        # Increment the leftmost non-zero part
                        if version.minor > 0:
                            upper_bound = Version(f"0.{version.minor + 1}.0")
                        elif version.patch > 0:
                            upper_bound = Version(f"0.0.{version.patch + 1}")
                        else: # ^0.0.0 -> <0.0.1
                            upper_bound = Version("0.0.1")

                        self.constraints.append({'op': '>=', 'version': version})
                        self.constraints.append({'op': '<', 'version': upper_bound})

                elif prefix == '~':
                    # ~1.2.3 is >=1.2.3, <1.3.0
                    # ~0.2.3 is >=0.2.3, <0.3.0
                    # ~0.0.3 is >=0.0.3, <0.0.4

                    # Increment MINOR if PATCH > 0, otherwise increment PATCH
                    if version.patch > 0:
                        next_patch = version.patch + 1
                        upper_bound = Version(f"{version.major}.{version.minor}.{next_patch}")
                    else:
                        next_minor = version.minor + 1
                        upper_bound = Version(f"{version.major}.{next_minor}.0")

                    self.constraints.append({'op': '>=', 'version': version})
                    self.constraints.append({'op': '<', 'version': upper_bound})
                continue

            # If we reach here, it's an unrecognized format
            raise ValueError(f"Unknown constraint format in range spec: {rc}")

    def __str__(self) -> str:
        # Return spec with all whitespace removed
        return self.spec.replace(' ', '')

    def contains(self, v: Version) -> bool:
        """Checks if the given Version satisfies all constraints in this Range."""
        if not isinstance(v, Version):
            return False

        if not self.constraints:
            # This should only happen if the spec was empty, which is caught in __init__
            return False

        for constraint in self.constraints:
            if 'wildcard' in constraint:
                continue # Wildcard always passes

            op = constraint['op']
            required_version = constraint['version']

            if op in self.OPERATORS:
                if not self.OPERATORS[op](v, required_version):
                    return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __repr__(self):
        return f"Range('{self.spec}')"

