                        upper_bound = Version(f"{version.major + 1}.0.0")
                        self.constraints.append({'op': '>=', 'version': version})
                        self.constraints.append({'op': '<', 'version': upper_bound})
                    else: # Major is 0
                        # Increment the leftmost non-zero part
                        if version.minor > 0:
                            upper_bound = Version(f"0.{version.minor + 1}.0")
                        elif version.patch > 0:
                            upper_bound = Version(f"0.0.{version.patch + 1}")
                        else: # ^0.0.0 -> <0.0.1
                            upper_bound = Version("0.0.1")

                        self.constraints.append({'op': '>=', 'version': version})
                        self.constraints.append({'op': '<', 'version': upper_bound})

                elif prefix == '~':
                    # ~1.2.3 is >=1.2.3, <1.3.0
                    # ~0.2.3 is >=0.2.3, <0.3.0
                    # ~0.0.3 is >=0.0.3, <0.0.4

                    # Increment MINOR if PATCH > 0, otherwise increment PATCH
                    if version.patch > 0:
                        next_patch = version.patch + 1
                        upper_bound = Version(f"{version.major}.{version.minor}.{next_patch}")
                    else:
                        next_minor = version.minor + 1
                        upper_bound = Version(f"{version.major}.{next_minor}.0")

                    self.constraints.append({'op': '>=', 'version': version})
                    self.constraints.append({'op': '<', 'version': upper_bound})
                continue

            # If we reach here, it's an unrecognized format
            raise ValueError(f"Unknown constraint format in range spec: {rc}")

    def __str__(self) -> str:
        # Return spec with all whitespace removed
        return self.spec.replace(' ', '')

    def contains(self, v: Version) -> bool:
        """Checks if the given Version satisfies all constraints in this Range."""
        if not isinstance(v, Version):
            return False

        if not self.constraints:
            # This should only happen if the spec was empty, which is caught in __init__
            return False

        for constraint in self.constraints:
            if 'wildcard' in constraint:
                continue # Wildcard always passes

            op = constraint['op']
            required_version = constraint['version']

            if op in self.OPERATORS:
                if not self.OPERATORS[op](v, required_version):
                    return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __repr__(self):
        return f"Range('{self.spec}')"

