class PackageIndex:
    """Manages available packages, versions, and their dependencies."""
    def __init__(self):
        # Structure: {name: {version_str: {dep_name: Range, ...}, ...}}
        self._data: Dict[str, Dict[str, Dict[str, Range]]] = defaultdict(dict)

    def add(self, name: str, version: str, requires: Optional[Dict[str, Range]] = None) -> None:
        """Adds a specific release of a package.
        Raises ValueError on duplicates or invalid inputs.
        """
        if not isinstance(name, str) or not name: raise ValueError("Package name must be a non-empty string.")
        if not isinstance(version, str) or not version: raise ValueError("Version string must be provided.")

        # Validation relies on external Version object
        try:
            Version(version)
        except ValueError:
            raise ValueError(f"Invalid version format: {version}")

        if version in self._data[name]:
            raise ValueError(f"Package {name} version {version} already exists.")

        self._data[name][version] = requires if requires is not None else {}

    def versions(self, name: str) -> List[Version]:
        """Returns a list of known Version objects for the package name, newest first."""
        if name not in self._data:
            return []

        # Convert string keys to Version objects for proper sorting
        version_list = [Version(v_str) for v_str in self._data[name].keys()]
        # Sort descending (newest first)
        version_list.sort(reverse=True)
        return version_list

    def requirements(self, name: str, version: str) -> Dict[str, Range]:
        """Returns a dict mapping dependency names to their Range for a specific version.
        Raises KeyError if the version is not found.
        """
        if name not in self._data or version not in self._data[name]:
            raise KeyError(f"Package {name} version {version} not found in index.")

        return self._data[name][version]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a pre-formatted dictionary structure.
        Data format: {name: {version: {dep: spec, ...}, ...}, ...}
        """
        index = cls()
        for name, versions_data in data.items():
            for version, requirements_data in versions_data.items():
                # Range specifications in input dict are strings; must be converted to Range objects
                try:
                    # We assume Range() can accept string specs
                    range_map = {dep: Range(spec) for dep, spec in requirements_data.items()}
                    index.add(name, version, range_map)
                except ValueError as e:
                    # Catch errors during Range initialization from dict data
                    print(f"Error building index for {name}@{version}: {e}")
        return index

