def read_records(lines: Iterable[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    """Reads an iterable of lines, parsing them and tracking line numbers for errors."""
    records: List[Record] = []
    bad_lines: List[int] = []

    for i, line in enumerate(lines, 1):
        stripped_line = line.strip()

        # Skip empty or whitespace-only lines
        if not stripped_line:
            continue

        try:
            record = parse_line(line, fmt)
            records.append(record)
        except ParseError as e:
            # Record the 1-based line number for parsing errors
            bad_lines.append(i)
        except ValueError as e:
            # Handle format errors from parse_line (e.g., bad fmt argument)
            # In a real CLI context, this should probably stop execution, 
            # but here we treat it as an unrecoverable parsing failure for the line.
            if "Unsupported format" in str(e):
                 # Re-raise format error to be caught by caller logic if needed
                 raise e
            else:
                 # Treat other ValueErrors as parse errors for tracking
                 bad_lines.append(i)

    return records, bad_lines
